common:
float edge(vec2 p) {
  float a = atan(p.y, p.x) - iTime * turn;
  float s = 6.2831853 / float(corners);
  float r = size * (1.0 + breathe * sin(iTime * 1.2566371)) * cos(3.14159265 / float(corners));
  return cos(floor(0.5 + a / s) * s - a) * length(p) - r;
}

float outline(float d) {
  return 1.0 - smoothstep(0.003, 0.009, abs(d));
}

passes.fragment:
float over(float v, float at) {
  return clamp((v - at) * 30.0, 0.0, 1.0);
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  vec2 t = texture2D(iChannel0, uv).rg;
  vec3 col = mix(deep, mid, over(t.r, 0.35));
  col = mix(col, bright, over(t.r, 0.7));
  col = mix(background, col, t.g * smoothstep(0.0, 0.1, t.r));
  float d = edge(p);
  col = mix(col, line, exp(-abs(d) * 60.0) * 0.3);
  gl_FragColor = vec4(mix(col, line, outline(d)), 1.0);
}
